import Lean
open Lean

run_cmd do
  let leaf : Language.SnapshotTree := {
    element := { diagnostics := .empty }, children := #[] }
  let child : Language.SnapshotTask Language.SnapshotTree :=
    Language.SnapshotTask.finished none leaf
  let root : Language.SnapshotTree := {
    element := { diagnostics := .empty },
    children := Array.replicate 10001 child }
  Elab.Command.logSnapshotTask (Language.SnapshotTask.finished none root)

example : True := by trivial

import Lean
open Lean

run_cmd do
  let leaf : Language.SnapshotTree := {
    element := { diagnostics := .empty }, children := #[] }
  let cancelTk ← IO.CancelToken.new
  cancelTk.set
  let child := Language.SnapshotTask.finished none leaf
  let root : Language.SnapshotTree := {
    element := { diagnostics := .empty },
    children := #[{ child with cancelTk? := some cancelTk }] }
  Elab.Command.logSnapshotTask (Language.SnapshotTask.finished none root)

example : True := by trivial

import Lean
open Lean

run_cmd do
  let leaf : Language.SnapshotTree := {
    element := { diagnostics := .empty, isFatal := true }, children := #[] }
  let root : Language.SnapshotTree := {
    element := { diagnostics := .empty },
    children := #[Language.SnapshotTask.finished none leaf] }
  Elab.Command.logSnapshotTask (Language.SnapshotTask.finished none root)

example : True := by trivial

import Lean
open Lean

run_cmd do
  let mut tree : Language.SnapshotTree := {
    element := { diagnostics := .empty }, children := #[] }
  for _ in [0:1000] do
    tree := {
      element := { diagnostics := .empty },
      children := #[Language.SnapshotTask.finished none tree] }
  Elab.Command.logSnapshotTask (Language.SnapshotTask.finished none tree)
  logInfo "DEEP_COMPLETED_1000_READY"

example : True := by trivial

import Lean
open Lean

run_cmd do
  let fileName := (← read).fileName
  let msg : Message :=
    { fileName, pos := ⟨3, 2⟩, severity := .error, data := "SNAPSHOT_ROOT_REPORTED_ERROR" }
  let log := (MessageLog.empty.add msg).markAllReported
  let diagnostics ← Language.Snapshot.Diagnostics.ofMessageLog log
  let tree : Language.SnapshotTree := {
    element := { diagnostics, isFatal := false },
    children := #[] }
  Elab.Command.logSnapshotTask (Language.SnapshotTask.finished none tree)

example : True := by trivial

